+			return qualified, nil
+		}
+	}
+	bare := types.EntityType(path)
+	if r.entityTypes[bare] || r.enumTypes[bare] {
+		return bare, nil
+	}
+	return "", fmt.Errorf("undefined entity type %q", path)
+}
